/** Resolves activation only; selected Delivery proof, shipping minimum and ranking remain evaluator obligations. */
export const resolveVoucherChoice = Effect.fn('PromotionVoucher.resolve')(function* resolve(
  port: VoucherOwnerPort,
  context: VoucherResolutionContext,
  code: string,
) {
  const normalizedCode = yield* normalizeVoucherCode(code);
  const found = yield* port.findVoucher(context.tenantId, normalizedCode);
  if (Option.isNone(found) || found.value.tenantId !== context.tenantId) {
    return yield* failure('UNKNOWN_CODE', 'Voucher code is unknown in this Tenant');
  }
  const row = found.value;
  if (row.voucher.normalizedCode !== normalizedCode) {
    return yield* failure('OWNER_UNVERIFIABLE', 'Voucher lookup attribution does not match the requested code');
  }
  const associated = yield* port.findPromotion(context.tenantId, row.voucher.promotionId);
  if (
    Option.isNone(associated) ||
    associated.value.tenantId !== context.tenantId ||
    associated.value.promotion.promotionId !== row.voucher.promotionId
  ) {
    return yield* failure('OWNER_UNVERIFIABLE', 'Bound Promotion attribution cannot be verified');
  }
  const { promotion } = associated.value;
  if (row.voucher.disabled || !isPromotionProspectivelyUsable(promotion, context.at)) {
    return yield* failure('INACTIVE_PROMOTION', 'Associated Promotion is inactive for this operation');
  }
  if (!promotion.meaning.eligibility.commercialScopes.some((scope) => sameScope(scope, context.commercialScope))) {
    return yield* failure('INELIGIBLE_CONTEXT', 'Voucher is not eligible in this commercial scope');
  }
  const targetMatches = Match.value(context.target).pipe(
    Match.when(
      { kind: 'PRODUCT' },
      ({ occurrence }) =>
        promotion.meaning.family === 'PRODUCT_VOUCHER' &&
        occurrence.selection.productRef.tenantId === context.tenantId &&
        isPromotionOccurrenceEligible(promotion.meaning, occurrence),
    ),
    Match.when({ kind: 'CART' }, () => promotion.meaning.family === 'CART_VOUCHER'),
    Match.when({ kind: 'SHIPPING' }, () => promotion.meaning.family === 'SHIPPING_VOUCHER'),
    Match.exhaustive,
  );
  if (!targetMatches) {
    return yield* failure('INELIGIBLE_CONTEXT', 'Voucher does not activate this target family');
  }
  return { promotion, voucher: row.voucher };
});

